/** Connected native player setup and authoritative assertions; gameplay interactions stay on the client route. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeGearInteractionClientFixture {
    public static final BlockPos ROOT=new BlockPos(0,99,0),RIDER=new BlockPos(8,99,0),ACK=new BlockPos(4,96,3);private static UUID actorId;private static int stage,checks,riderTicks;private static double startY;
    public static boolean enabled(){return Boolean.getBoolean("vandorlabs.gearInteractionClientCheck");}
    public record Mode(int operation) implements CustomPacketPayload {public static final Type<Mode> TYPE=new Type<>(ResourceLocation.parse("vandorlabs:gear_interaction_fixture"));public Type<? extends CustomPacketPayload> type(){return TYPE;}}
    @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Packets{@SubscribeEvent public static void register(net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent event){if(enabled())event.registrar("1").playToServer(Mode.TYPE,new StreamCodec<RegistryFriendlyByteBuf,Mode>(){public Mode decode(RegistryFriendlyByteBuf b){if(b.readableBytes()!=1)throw new IllegalArgumentException();return new Mode(b.readUnsignedByte());}public void encode(RegistryFriendlyByteBuf b,Mode p){b.writeByte(p.operation);}},(p,context)->context.enqueueWork(()->{if(context.player() instanceof ServerPlayer actor)apply(actor,p.operation);}));}}
    private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Native gear interaction server stage="+stage+": "+why);}
    private static NativeGearEntity root(ServerPlayer actor,BlockPos pos){var root=NativeGearFormation.at(actor.level(),pos);need(root!=null&&!root.inert()&&root.controller(),"healthy installed root "+pos);return root;}
    private static void held(ServerPlayer actor,ItemStack stack){actor.getInventory().selected=0;actor.setItemInHand(InteractionHand.MAIN_HAND,stack);actor.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);actor.connection.send(new ClientboundSetCarriedItemPacket(0));actor.connection.send(new ClientboundContainerSetSlotPacket(-2,0,0,stack.copy()));actor.inventoryMenu.broadcastChanges();}
    @SubscribeEvent public static void login(PlayerEvent.PlayerLoggedInEvent event){if(!enabled()||!(event.getEntity() instanceof ServerPlayer actor))return;actorId=actor.getUUID();var world=actor.serverLevel();for(int x=-5;x<=14;x++)for(int z=-5;z<=5;z++){world.setBlock(new BlockPos(x,95,z),Blocks.STONE.defaultBlockState(),3);for(int y=96;y<=104;y++)world.setBlock(new BlockPos(x,y,z),Blocks.AIR.defaultBlockState(),3);}for(var pos:List.of(ROOT,RIDER))world.setBlock(pos.above(),Blocks.STONE.defaultBlockState(),3);actor.setGameMode(GameType.SURVIVAL);actor.getInventory().clearContent();held(actor,new ItemStack(NativeGearBindings.ITEMS.get(NativeGearDefinition.ROTATING.id),2));actor.connection.teleport(.5,96,-3,0,0);System.out.println("[vandorlabs][gear-interaction-client] setup PASS");}
    private static void miningView(ServerPlayer actor,NativeGearEntity root){for(var box:root.payload().boxes(root,root.progress()))for(var side:List.of(Direction.NORTH,Direction.SOUTH,Direction.EAST,Direction.WEST)){var target=box.getCenter();var horizontal=target.add(Vec3.atLowerCornerOf(side.getNormal()).scale(3.5));var eye=new Vec3(horizontal.x,96+actor.getEyeHeight(),horizontal.z);var look=target.subtract(eye).normalize();float yaw=(float)Math.toDegrees(Math.atan2(-look.x,look.z)),pitch=(float)-Math.toDegrees(Math.asin(look.y));actor.setPos(eye.x,eye.y-actor.getEyeHeight(),eye.z);actor.setYRot(yaw);actor.setXRot(pitch);var hit=NativeGearHarvest.target(actor);if(hit!=null&&hit.owner()==root){actor.connection.teleport(actor.getX(),actor.getY(),actor.getZ(),yaw,pitch);return;}}throw new AssertionError("No visible captured mining ray");}
    private static void apply(ServerPlayer actor,int operation){need(actor.getUUID().equals(actorId)&&operation==stage,"actor/order op="+operation);var world=actor.serverLevel();switch(operation){
        case 0->{var root=root(actor,ROOT);need(root.assembly().columnHeight()==2&&actor.getMainHandItem().isEmpty(),"two ordinary Survival Rotating placements");world.setBlock(ROOT.below(2),Blocks.CHEST.defaultBlockState(),3);var chest=(ChestBlockEntity)world.getBlockEntity(ROOT.below(2));chest.setItem(0,new ItemStack(Items.DIAMOND,7));chest.setChanged();held(actor,new ItemStack(VandorLabsBootstrap.CONFIGURIZER.get()));}
        case 1->{var root=root(actor,ROOT);need(root.progress()==0&&root.payload()!=null&&!root.payload().materialized()&&!NativeGearJournal.busy(root),"sole captured Chest at fractional LEVEL endpoint");need(root.payload().endpoint(root,0).isEmpty(),"fractional native endpoint negative");held(actor,new ItemStack(Items.DIAMOND_AXE));miningView(actor,root);System.out.println("[vandorlabs][gear-interaction-client] capture PASS");}
        case 2->{var root=root(actor,ROOT);need(root.payload()==null&&!NativeGearJournal.busy(root),"actual held attack completed journal harvest");int diamonds=0,chests=0;for(var item:world.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(ROOT).inflate(10))){need(!NativeGearDropEscrow.held(item),"drops usable only after native actor barrier");if(item.getItem().is(Items.DIAMOND))diamonds+=item.getItem().getCount();if(item.getItem().is(Items.CHEST))chests+=item.getItem().getCount();}need(diamonds==7&&chests==1,"seven diamonds and one Chest exactly once");need(actor.getMainHandItem().is(Items.DIAMOND_AXE)&&actor.getMainHandItem().getDamageValue()==1,"ordinary Survival tool wear once");held(actor,new ItemStack(NativeGearBindings.ITEMS.get(NativeGearDefinition.EXTENDER.id),2));actor.connection.teleport(8.5,96,-3,0,0);System.out.println("[vandorlabs][gear-interaction-client] mining PASS");}
        case 3->{var root=root(actor,RIDER);need(root.assembly().columnHeight()==2&&actor.getMainHandItem().isEmpty(),"two ordinary Survival Extender placements");held(actor,new ItemStack(NativeGearBindings.ITEMS.get(NativeGearDefinition.PLATE.id),3));}
        case 4->{var root=root(actor,RIDER);need(root.assembly().feet().size()==3&&actor.getMainHandItem().isEmpty(),"three connected unsupported Plate cells");startY=RIDER.getY()-2+3/16D;actor.connection.teleport(10.5,startY,.5,180,70);root.authorize(actor);System.out.println("[vandorlabs][gear-interaction-client] riding PASS setup");}
        case 5->{var root=root(actor,RIDER);need(root.progress()==0&&!root.blocked()&&riderTicks>8,"actual rider completed native stroke");need(actor.getY()>startY+1.4&&Math.abs(actor.getX()-10.5)<.05&&Math.abs(actor.getZ()-.5)<.05,"player transported vertically without cloning");}
        case 6->{var root=root(actor,RIDER);need(root.progress()==1&&!root.blocked()&&Math.abs(actor.getY()-startY)<.1,"player reversal returns to actual Plate");need(root.members().size()==5&&actor.serverLevel().getEntitiesOfClass(net.minecraft.world.entity.player.Player.class,new AABB(RIDER).inflate(12)).size()==1,"original five components and exactly one native player");System.out.println("[vandorlabs][gear-interaction-client] completed PASS checks="+checks+" actualMiningInput/terrainActorWAL/toolWear/physicalPlayerRide/reversal/overhangRootInteraction");}
        default->throw new IllegalArgumentException("Gear interaction fixture operation");}world.setBlock(ACK.east(operation),Blocks.STONE.defaultBlockState(),3);stage++;}
    @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post event){if(!enabled()||stage<5||stage>6)return;var actor=event.getServer().getPlayerList().getPlayer(actorId);if(actor==null)return;var root=root(actor,RIDER);if(root.progress()>0&&root.progress()<1){riderTicks++;need(!root.blocked(),"actual rider unobstructed stroke");double top=NativeGearGeometry.mechanismBoxes(root,root.progress()).stream().filter(box->box.minX<10.5&&box.maxX>10.5&&box.minZ<.5&&box.maxZ>.5).mapToDouble(box->box.maxY).max().orElseThrow();need(Math.abs(actor.getBoundingBox().minY-top)<.12,"same-tick rider support position="+actor.getY()+" top="+top);}}
    @SubscribeEvent public static void logout(PlayerEvent.PlayerLoggedOutEvent event){if(enabled()&&event.getEntity().getUUID().equals(actorId)){need(stage==7,"completed interaction journey");System.out.println("[vandorlabs][gear-interaction-client] logout PASS");}}
}
